package com.example.todo.controller; import com.example.todo.dto.*; import com.example.todo.service.TodoService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.Page; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/todos") @RequiredArgsConstructor public class TodoController {private final TodoService service;@GetMapping public Page<TodoResponse> all(Authentication a,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="5")int size,@RequestParam(required=false)String search,@RequestParam(required=false)Boolean completed){return service.findAll(a.getName(),page,size,search,completed);}@GetMapping("/{id}") public TodoResponse one(@PathVariable Long id,Authentication a){return service.one(id,a.getName());}@PostMapping public ResponseEntity<TodoResponse> create(@Valid @RequestBody TodoRequest r,Authentication a){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(r,a.getName()));}@PutMapping("/{id}") public TodoResponse update(@PathVariable Long id,@Valid @RequestBody TodoRequest r,Authentication a){return service.update(id,r,a.getName());}@PatchMapping("/{id}/complete") public TodoResponse toggle(@PathVariable Long id,Authentication a){return service.toggle(id,a.getName());}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id,Authentication a){service.delete(id,a.getName());}}
